using System.IO;
using SituationalPractice;
class ExportHooks
{
    static void Main() { File.WriteAllBytes("Evidence/DefaultPracticeRestore.bin",NativeRuntime.BuildDefaultPracticeRestore(0x140000000,0x200000000)); File.WriteAllBytes("Evidence/EarlyPlayCall.bin",NativeRuntime.BuildEarlyPlayCall(0x140000000,0x200000000)); File.WriteAllBytes("Evidence/ModeText.bin",NativeRuntime.BuildModeText(0x140000000,0x200000000)); File.WriteAllBytes("Evidence/ModeDispatch.bin",NativeRuntime.BuildModeDispatch(0x140000000,0x200000000)); File.WriteAllBytes("Evidence/PlayCallRefresh.bin",NativeRuntime.BuildPlayCallRefresh(0x140000000,0x200000000)); File.WriteAllBytes("Evidence/DefenseCommit.bin",NativeRuntime.BuildDefenseCommit(0x140000000,0x200000000)); for(int i=0;i<3;i++)File.WriteAllBytes("Evidence/Gate"+i+".bin",NativeRuntime.BuildGate(0x140000000,0x200000000,i)); File.WriteAllBytes("Evidence/Trace.bin",NativeRuntime.BuildTrace(0x140000000,0x200000000)); File.WriteAllBytes("Evidence/HudEntry.bin",NativeRuntime.BuildHudEntry(0x140000000,0x200000000));File.WriteAllBytes("Evidence/LineGuard.bin",NativeRuntime.BuildLineGuard(0x140000000,0x200000000));File.WriteAllBytes("Evidence/StatsVisibility.bin",NativeRuntime.BuildStatsVisibility(0x140000000,0x200000000));File.WriteAllBytes("Evidence/SessionStats.bin",NativeRuntime.BuildSessionStats(0x140000000,0x200000000));File.WriteAllBytes("Evidence/ReturnGuard.bin",NativeRuntime.BuildReturnGuard(0x140000000,0x200000000));File.WriteAllBytes("Evidence/PlayCallTick.bin",NativeRuntime.BuildPlayCallTick(0x140000000,0x200000000));File.WriteAllBytes("Evidence/PracticePlayCallUi.bin",NativeRuntime.BuildPracticePlayCallUi(0x140000000,0x200000000));File.WriteAllBytes("Evidence/InitialPlayCallTick.bin",NativeRuntime.BuildInitialPlayCallTick(0x140000000,0x200000000));File.WriteAllBytes("Evidence/InitialSetupTick.bin",NativeRuntime.BuildInitialSetupTick(0x140000000,0x200000000)); }
}

